import type { Metadata } from "next";
import Link from "next/link";

import { CompareBars, type CompareRow } from "@/components/modelcharts";
import { Badge, Page, Panel } from "@/components/ui";
import { BRAHMACHARINI, KALARATRI, KALARATRI_BGL, KATYAYANI, MODELS, SHAILAPUTRI, STAGES, statusOf, type ModelStatus } from "@/lib/navadurga";

export const metadata: Metadata = {
  title: "Sati models",
  description:
    "The nine models Sati, the investigation agent, runs on — each trained and tested on real data, with every number generated by the training run.",
};

const STATUS: Record<ModelStatus, { label: string; status: "ok" | "warning" | "neutral" }> = {
  trained: { label: "trained", status: "ok" },
  training: { label: "training", status: "warning" },
  planned: { label: "planned", status: "neutral" },
};

const FOLD_NAMES: Record<string, string> = {
  ob: "Online Boutique",
  ss: "Sock Shop",
  tt: "Train Ticket",
};

const pct = (v: number) => `${(v * 100).toFixed(1)}%`;

/**
 * The Sati model family (adr/Navadurga): nine models, named for the nine forms
 * of Navadurga, each doing the job that fits its form. The job leads every
 * card; the name follows it. Numbers come from the training workflow's results
 * file and nowhere else.
 */
export default function ModelsPage() {
  const r = KATYAYANI;
  const loso = r.pooled["leave-one-system-out"];
  const trained = MODELS.filter((m) => statusOf(m) === "trained").length;
  const s = SHAILAPUTRI.pending ? null : SHAILAPUTRI;
  const statistical = s
    ? Object.keys(s.mean_across_families).filter((k) => k !== "shailaputri-v0")
    : [];
  const bestStatistical = s
    ? statistical.reduce((best, k) =>
        s.mean_across_families[k].f1 > s.mean_across_families[best].f1 ? k : best,
      statistical[0])
    : null;
  const detectRows: CompareRow[] =
    s && bestStatistical
      ? s.folds.map((f) => ({
          label: f.held_out,
          hint: `family never seen in training · best statistical: ${bestStatistical}`,
          model: { value: f.detectors["shailaputri-v0"].f1, ci: [] },
          baseline: { value: f.detectors[bestStatistical].f1, ci: [] },
          n: f.series,
        }))
      : [];

  const systemRows: CompareRow[] = r.splits
    .filter((s) => s.scheme === "leave-one-system-out")
    .map((s) => ({
      label: FOLD_NAMES[s.fold] ?? s.fold,
      hint: `never seen in training · ${s.train_cases} training incidents`,
      model: { value: s.sati["ac@1"], ci: s.sati["ac@1_ci"] },
      baseline: { value: s.baseline["ac@1"], ci: s.baseline["ac@1_ci"] },
      n: s.sati.n,
    }));

  const faultRows: CompareRow[] = r.splits
    .filter((s) => s.scheme === "held-out-fault")
    .map((s) => ({
      label: s.fold,
      hint: "fault type never seen in training",
      model: { value: s.sati["ac@1"], ci: s.sati["ac@1_ci"] },
      baseline: { value: s.baseline["ac@1"], ci: s.baseline["ac@1_ci"] },
      n: s.sati.n,
    }));

  if (r.stress_re3) {
    faultRows.push({
      label: "code-level faults (RE3)",
      hint: "a whole suite never trained on",
      model: { value: r.stress_re3.sati["ac@1"], ci: r.stress_re3.sati["ac@1_ci"] },
      baseline: { value: r.stress_re3.baseline["ac@1"], ci: r.stress_re3.baseline["ac@1_ci"] },
      n: r.stress_re3.sati.n,
    });
  }

  return (
    <Page
      title="Sati models"
      description="Nine models that Sati, the investigation agent, runs on — each named for one of the nine forms of Navadurga and given the job that fits it. Every model is built here and trained and tested on real public data, in the cloud."
    >
      <section className="grid gap-3 sm:grid-cols-4">
        <Tile label="Models" value="9" hint="one per stage of the loop" />
        <Tile label="Trained" value={`${trained} of 9`} hint="the rest are planned in Block H" />
        <Tile label="Katyayani, unseen systems" value={pct(loso.sati["ac@1"])} hint={`top-1 root cause · baseline ${pct(loso.baseline["ac@1"])}`} />
        <Tile label="Real incidents tested" value={String(r.dataset.cases)} hint={`${r.dataset.name} · pinned ${r.dataset.revision.slice(0, 8)}`} />
      </section>

      <Panel title="Where each model sits in the loop">
        <ol className="grid gap-3 sm:grid-cols-4 lg:grid-cols-7">
          {STAGES.map((stage) => (
            <li key={stage} className="rounded-lg border border-[rgb(var(--edge))] bg-[rgb(var(--ground))] p-3">
              <p className="label">{stage}</p>
              <ul className="mt-2 space-y-1">
                {MODELS.filter((m) => m.stage === stage).map((m) => (
                  <li key={m.id} className="flex items-center gap-1.5 text-sm">
                    <span
                      aria-hidden="true"
                      className={`h-1.5 w-1.5 rounded-full ${statusOf(m) === "trained" ? "bg-[rgb(var(--ok))]" : "bg-[rgb(var(--edge-strong))]"}`}
                    />
                    <a href={`#${m.id}`} className="focusable rounded hover:text-[rgb(var(--astra))]">{m.name}</a>
                  </li>
                ))}
              </ul>
            </li>
          ))}
        </ol>
      </Panel>

      <ul className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
        {MODELS.map((m) => (
          <li
            key={m.id}
            id={m.id}
            data-model={m.id}
            className={`scroll-mt-24 rounded-xl border bg-[rgb(var(--panel))] p-5 ${
              statusOf(m) === "trained" ? "border-[rgb(var(--astra))]/50" : "border-[rgb(var(--edge))]"
            }`}
          >
            <div className="flex items-center gap-2">
              <span className="tnum inline-flex h-7 w-7 items-center justify-center rounded-full bg-[rgb(var(--raised))] text-xs font-semibold">
                {m.n}
              </span>
              <span className="label">{m.stage}</span>
              <span className="ml-auto">
                <Badge status={STATUS[statusOf(m)].status}>{STATUS[statusOf(m)].label}</Badge>
              </span>
            </div>
            <p className="mt-3 text-[0.9375rem] leading-snug text-[rgb(var(--ink))]">{m.job}</p>
            <p className="mt-3 text-sm">
              <span className="font-semibold">{m.name}</span>
              <span className="text-[rgb(var(--faint))]"> — {m.nature}</span>
            </p>
            <p className="mt-3 flex flex-wrap gap-1.5">
              {m.data.map((d) => (
                <span key={d} className="rounded-full border border-[rgb(var(--edge))] px-2 py-0.5 text-[11px] text-[rgb(var(--muted))]">
                  {d}
                </span>
              ))}
              <span className="mono ml-auto text-[11px] text-[rgb(var(--faint))]">{m.task}</span>
            </p>
            {m.id === "sati-katyayani" && (
              <p className="mt-3 border-t border-[rgb(var(--edge))] pt-3 text-xs text-[rgb(var(--muted))]">
                Top-1 root cause on systems never seen in training:{" "}
                <strong className="text-[rgb(var(--ink))]">{pct(loso.sati["ac@1"])}</strong> vs{" "}
                {pct(loso.baseline["ac@1"])} without learning.{" "}
                <a href="#katyayani-results" className="focusable rounded text-[rgb(var(--astra))] hover:underline">Results ↓</a>
              </p>
            )}
          </li>
        ))}
      </ul>

      {s && (
        <section id="shailaputri-results" className="scroll-mt-24 space-y-6">
          <div>
            <h2 className="text-xl font-semibold tracking-tight">Shailaputri — anomalies in real metric series</h2>
            <p className="mt-1.5 max-w-3xl text-sm leading-relaxed text-[rgb(var(--muted))]">
              Trained on {s.dataset.series} real series from NAB, each family of series held out in turn, and scored
              online by the same harness as the four statistical detectors on exactly the same series. F1 is
              read together with false alarms per 1000 points, never alone.
            </p>
          </div>
          <div className="grid gap-6 lg:grid-cols-2">
            <Panel title="F1 on a family it never saw" aside="vs the best statistical detector">
              <CompareBars rows={detectRows} metric="Episode recall and point precision combined; the threshold was chosen on training families only." />
            </Panel>
            <Panel title="Mean across held-out families">
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="text-left text-xs text-[rgb(var(--faint))]">
                      <th className="py-2 pr-3 font-normal">Detector</th>
                      <th className="py-2 pr-3 text-right font-normal">F1</th>
                      <th className="py-2 pr-3 text-right font-normal">Recall</th>
                      <th className="py-2 pr-3 text-right font-normal">False alarms / 1000</th>
                      <th className="py-2 text-right font-normal">Lead</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[rgb(var(--edge))]">
                    {Object.entries(s.mean_across_families).map(([name, m]) => (
                      <tr key={name}>
                        <td className="py-2 pr-3">{name === "shailaputri-v0" ? <strong>Shailaputri</strong> : name}</td>
                        <td className="tnum py-2 pr-3 text-right">{m.f1.toFixed(3)}</td>
                        <td className="tnum py-2 pr-3 text-right">{m.recall.toFixed(3)}</td>
                        <td className="tnum py-2 pr-3 text-right">{m.false_alarms_per_1000.toFixed(1)}</td>
                        <td className="tnum py-2 text-right">{m.mean_lead.toFixed(1)}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              <p className="mt-3 text-xs leading-relaxed text-[rgb(var(--faint))]">
                NAB&rsquo;s labels are windows, and Wu &amp; Keogh (2021) show several NAB series are trivial or mislabelled;
                these numbers inherit those limits.
              </p>
            </Panel>
          </div>
        </section>
      )}

      {!BRAHMACHARINI.pending && (
        <section id="brahmacharini-results" className="scroll-mt-24 space-y-4">
          <div>
            <h2 className="text-xl font-semibold tracking-tight">Brahmacharini — from behaviour to the technique it is</h2>
            <p className="mt-1.5 max-w-3xl text-sm leading-relaxed text-[rgb(var(--muted))]">
              Each test query is a real description of how an attacker behaved, written about one of{" "}
              {BRAHMACHARINI.dataset.test_sources_unseen} groups, malware families or tools never seen in training. The
              model ranks all {BRAHMACHARINI.dataset.techniques} ATT&amp;CK techniques; the same queries go to BM25 and to
              the embedder Smriti uses today.
            </p>
          </div>
          <Panel title="Held-out behaviour descriptions" aside={`n = ${Object.values(BRAHMACHARINI.test)[0]?.n ?? 0}`}>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="text-left text-xs text-[rgb(var(--faint))]">
                    <th className="py-2 pr-3 font-normal">Retriever</th>
                    <th className="py-2 pr-3 text-right font-normal">Recall@1</th>
                    <th className="py-2 pr-3 text-right font-normal">Recall@5</th>
                    <th className="py-2 pr-3 text-right font-normal">Recall@10</th>
                    <th className="py-2 text-right font-normal">MRR</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[rgb(var(--edge))]">
                  {Object.entries(BRAHMACHARINI.test).map(([name, m]) => (
                    <tr key={name}>
                      <td className="py-2 pr-3">{name.startsWith("brahmacharini") ? <strong>Brahmacharini</strong> : name}</td>
                      <td className="tnum py-2 pr-3 text-right">{m["recall@1"].toFixed(3)}</td>
                      <td className="tnum py-2 pr-3 text-right">{m["recall@5"].toFixed(3)}</td>
                      <td className="tnum py-2 pr-3 text-right">{m["recall@10"].toFixed(3)}</td>
                      <td className="tnum py-2 text-right">{m.mrr.toFixed(3)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </Panel>
        </section>
      )}

      {!KALARATRI.pending && (
        <section id="kalaratri-results" className="scroll-mt-24 space-y-4">
          <div>
            <h2 className="text-xl font-semibold tracking-tight">Kalaratri — anomalies hidden in real logs</h2>
            <p className="mt-1.5 max-w-3xl text-sm leading-relaxed text-[rgb(var(--muted))]">
              Two real logs, each split by time — trained on the earliest part, tested on the latest — against two
              classic detectors on exactly the same test data. HDFS is the easy benchmark; BGL, a supercomputer&apos;s
              log over seven months, is the hard one.
            </p>
          </div>
          {[KALARATRI, KALARATRI_BGL].filter((run) => !run.pending).map((run) => (
          <Panel
            key={run.dataset.name}
            title={`${run.dataset.name}: ${run.dataset.split.test.toLocaleString()} held-out ${run.dataset.unit ?? "HDFS blocks"}`}
            aside={`${(run.dataset.anomaly_share * 100).toFixed(1)}% anomalous · later in time than anything trained on`}
          >
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="text-left text-xs text-[rgb(var(--faint))]">
                    <th className="py-2 pr-3 font-normal">Detector</th>
                    <th className="py-2 pr-3 text-right font-normal">Precision</th>
                    <th className="py-2 pr-3 text-right font-normal">Recall</th>
                    <th className="py-2 pr-3 text-right font-normal">F1</th>
                    <th className="py-2 text-right font-normal">False-positive rate</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[rgb(var(--edge))]">
                  {Object.entries(run.test).map(([name, m]) => (
                    <tr key={name}>
                      <td className="py-2 pr-3">{name.startsWith("kalaratri") ? <strong>Kalaratri</strong> : name}</td>
                      <td className="tnum py-2 pr-3 text-right">{m.precision.toFixed(3)}</td>
                      <td className="tnum py-2 pr-3 text-right">{m.recall.toFixed(3)}</td>
                      <td className="tnum py-2 pr-3 text-right">{m.f1.toFixed(3)}</td>
                      <td className="tnum py-2 text-right">{m.false_positive_rate.toFixed(4)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            <p className="mt-3 text-xs text-[rgb(var(--faint))]">{run.weights_note}</p>
          </Panel>
          ))}
        </section>
      )}

      <section id="katyayani-results" className="scroll-mt-24 space-y-6">
        <div>
          <h2 className="text-xl font-semibold tracking-tight">Katyayani — root cause, on real failures</h2>
          <p className="mt-1.5 max-w-3xl text-sm leading-relaxed text-[rgb(var(--muted))]">
            Trained and tested on {r.dataset.cases} real fault-injection incidents from RCAEval across three
            microservice systems. Each row holds something out of training entirely, and both bars are
            scored on exactly the same incidents. Hover a row for its interval.
          </p>
        </div>

        <div className="grid gap-6 lg:grid-cols-2">
          <Panel title="A system it has never seen" aside="top-1 accuracy">
            <CompareBars rows={systemRows} metric="Share of incidents where the true root-cause service is ranked first." />
          </Panel>
          <Panel title="A kind of failure it has never seen" aside="top-1 accuracy">
            <CompareBars rows={faultRows} metric="Each fault type held out of training in turn; RE3 never trained on at all." />
          </Panel>
        </div>

        <div className="grid gap-6 lg:grid-cols-2">
          <Panel title="Pooled results" aside="Wilson 95% intervals">
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="text-left text-xs text-[rgb(var(--faint))]">
                    <th className="py-2 pr-3 font-normal">Held out</th>
                    <th className="py-2 pr-3 font-normal">Model</th>
                    <th className="py-2 pr-3 text-right font-normal">Top-1</th>
                    <th className="py-2 pr-3 text-right font-normal">Top-3</th>
                    <th className="py-2 text-right font-normal">Avg@5</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-[rgb(var(--edge))]">
                  {Object.entries(r.pooled).flatMap(([scheme, p]) =>
                    (["sati", "baseline"] as const).map((who) => (
                      <tr key={scheme + who}>
                        <td className="py-2 pr-3 text-xs text-[rgb(var(--muted))]">{scheme.replaceAll("-", " ")}</td>
                        <td className="py-2 pr-3">{who === "sati" ? <strong>Katyayani</strong> : "baseline"}</td>
                        <td className="tnum py-2 pr-3 text-right">{pct(p[who]["ac@1"])}</td>
                        <td className="tnum py-2 pr-3 text-right">{pct(p[who]["ac@3"])}</td>
                        <td className="tnum py-2 text-right">{pct(p[who]["avg@5"])}</td>
                      </tr>
                    )),
                  )}
                  {r.ablation_no_n_series && (
                    <tr>
                      <td className="py-2 pr-3 text-xs text-[rgb(var(--muted))]">unseen system, without series count</td>
                      <td className="py-2 pr-3"><strong>Katyayani</strong> (ablated)</td>
                      <td className="tnum py-2 pr-3 text-right">{pct(r.ablation_no_n_series.sati["ac@1"])}</td>
                      <td className="tnum py-2 pr-3 text-right">{pct(r.ablation_no_n_series.sati["ac@3"])}</td>
                      <td className="tnum py-2 text-right">{pct(r.ablation_no_n_series.sati["avg@5"])}</td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
            <p className="mt-3 text-xs leading-relaxed text-[rgb(var(--faint))]">
              The ablated row removes a feature that could let the model guess the <em>kind</em> of service
              rather than read what changed. It scores the same — the model is reading the metrics.
            </p>
          </Panel>

          {r.example_explanation && (
            <Panel title="What a ranking cites" aside={<span className="mono">{r.example_explanation.case}</span>}>
              <p className="mb-3 text-sm text-[rgb(var(--muted))]">
                Every ranking names the metric series behind it, so the answer can be checked — the same rule
                as for any hypothesis Sati makes. Root cause here: <span className="mono text-[rgb(var(--ink))]">{r.example_explanation.service}</span>.
              </p>
              <ul className="space-y-2">
                {r.example_explanation.reasons.map((reason) => (
                  <li key={reason.feature} className="flex items-center gap-3 rounded-lg border border-[rgb(var(--edge))] px-3 py-2 text-sm">
                    <span className="mono text-xs">{reason.feature}</span>
                    <span className="text-xs text-[rgb(var(--faint))]">from</span>
                    <span className="mono text-xs text-[rgb(var(--astra))]">{reason.series ?? "—"}</span>
                    <span className="tnum ml-auto text-xs text-[rgb(var(--muted))]">+{reason.contribution}</span>
                  </li>
                ))}
              </ul>
            </Panel>
          )}
        </div>

        <p className="text-xs leading-relaxed text-[rgb(var(--faint))]">
          The incident&rsquo;s injection time is given to the model, which is RCAEval&rsquo;s standard setting; a
          deployed system has to detect onset itself. Model sha256 <span className="mono">{r.model_sha256.slice(0, 16)}…</span>.
          These models were designed, written and trained by an AI assistant under the owner&rsquo;s direction.{" "}
          <Link href="/evaluation" className="focusable rounded underline decoration-dotted underline-offset-2 hover:text-[rgb(var(--astra))]">
            Evaluation
          </Link>
        </p>
      </section>
    </Page>
  );
}

function Tile({ label, value, hint }: { label: string; value: string; hint: string }) {
  return (
    <div className="rounded-xl border border-[rgb(var(--edge))] bg-[rgb(var(--panel))] p-4">
      <p className="label">{label}</p>
      <p className="tnum mt-1 text-2xl font-semibold">{value}</p>
      <p className="mt-0.5 text-xs text-[rgb(var(--faint))]">{hint}</p>
    </div>
  );
}
